import * as React from 'react'
import { Link } from 'gatsby'

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"
import gridColours from "../data/grid-colours.json"

// ============================================
// Types & constants
// ============================================
interface Boid {
  x: number
  y: number
  vx: number
  vy: number
  colour: string
}

const MOBILE_BREAKPOINT = 600
const BOID_COUNT_DESKTOP = 120
const BOID_COUNT_MOBILE = 60

const SEP_RADIUS = 25
const ALIGN_RADIUS = 50
const COHESION_RADIUS = 80
const CURSOR_RADIUS = 150
const EDGE_MARGIN = 40

const SEP_WEIGHT = 1.5
const ALIGN_WEIGHT = 1.0
const COHESION_WEIGHT = 1.0
const CURSOR_WEIGHT = 0.8
const EDGE_WEIGHT = 1.0

const MAX_SPEED = 3
const MAX_FORCE = 0.15

const TRAIL_ALPHA = 0.15

// ============================================
// Helpers
// ============================================
const limit = (vx: number, vy: number, max: number): [number, number] => {
  const mag = Math.sqrt(vx * vx + vy * vy)
  if (mag > max) {
    const scale = max / mag
    return [vx * scale, vy * scale]
  }
  return [vx, vy]
}

const createBoids = (count: number, width: number, height: number): Boid[] =>
  Array.from({ length: count }, () => ({
    x: Math.random() * width,
    y: Math.random() * height,
    vx: (Math.random() - 0.5) * 2,
    vy: (Math.random() - 0.5) * 2,
    colour: gridColours[Math.floor(Math.random() * gridColours.length)],
  }))

// ============================================
// Simulation step
// ============================================
const updateBoids = (
  boids: Boid[],
  width: number,
  height: number,
  cursorX: number,
  cursorY: number,
  cursorActive: boolean,
  repelMode: boolean,
) => {
  const len = boids.length

  for (let i = 0; i < len; i++) {
    const b = boids[i]

    // Accumulators for steering forces
    let sepX = 0, sepY = 0, sepCount = 0
    let alignX = 0, alignY = 0, alignCount = 0
    let cohX = 0, cohY = 0, cohCount = 0

    for (let j = 0; j < len; j++) {
      if (i === j) continue
      const other = boids[j]
      const dx = other.x - b.x
      const dy = other.y - b.y
      const dist = Math.sqrt(dx * dx + dy * dy)

      if (dist < SEP_RADIUS && dist > 0) {
        sepX -= dx / dist
        sepY -= dy / dist
        sepCount++
      }
      if (dist < ALIGN_RADIUS) {
        alignX += other.vx
        alignY += other.vy
        alignCount++
      }
      if (dist < COHESION_RADIUS) {
        cohX += other.x
        cohY += other.y
        cohCount++
      }
    }

    let fx = 0, fy = 0

    // Separation
    if (sepCount > 0) {
      sepX /= sepCount
      sepY /= sepCount
      const [sx, sy] = limit(sepX, sepY, MAX_FORCE)
      fx += sx * SEP_WEIGHT
      fy += sy * SEP_WEIGHT
    }

    // Alignment
    if (alignCount > 0) {
      alignX /= alignCount
      alignY /= alignCount
      const [ax, ay] = limit(alignX - b.vx, alignY - b.vy, MAX_FORCE)
      fx += ax * ALIGN_WEIGHT
      fy += ay * ALIGN_WEIGHT
    }

    // Cohesion
    if (cohCount > 0) {
      cohX /= cohCount
      cohY /= cohCount
      const dx = cohX - b.x
      const dy = cohY - b.y
      const [cx, cy] = limit(dx, dy, MAX_FORCE)
      fx += cx * COHESION_WEIGHT
      fy += cy * COHESION_WEIGHT
    }

    // Cursor influence
    if (cursorActive) {
      const cdx = cursorX - b.x
      const cdy = cursorY - b.y
      const cdist = Math.sqrt(cdx * cdx + cdy * cdy)
      if (cdist < CURSOR_RADIUS && cdist > 0) {
        const strength = (1 - cdist / CURSOR_RADIUS) * MAX_FORCE * 2
        if (repelMode) {
          fx -= (cdx / cdist) * strength * CURSOR_WEIGHT
          fy -= (cdy / cdist) * strength * CURSOR_WEIGHT
        } else {
          fx += (cdx / cdist) * strength * CURSOR_WEIGHT
          fy += (cdy / cdist) * strength * CURSOR_WEIGHT
        }
      }
    }

    // Edge avoidance
    if (b.x < EDGE_MARGIN) fx += (EDGE_MARGIN - b.x) / EDGE_MARGIN * MAX_FORCE * EDGE_WEIGHT
    if (b.x > width - EDGE_MARGIN) fx -= (b.x - (width - EDGE_MARGIN)) / EDGE_MARGIN * MAX_FORCE * EDGE_WEIGHT
    if (b.y < EDGE_MARGIN) fy += (EDGE_MARGIN - b.y) / EDGE_MARGIN * MAX_FORCE * EDGE_WEIGHT
    if (b.y > height - EDGE_MARGIN) fy -= (b.y - (height - EDGE_MARGIN)) / EDGE_MARGIN * MAX_FORCE * EDGE_WEIGHT

    // Apply forces
    b.vx += fx
    b.vy += fy
    ;[b.vx, b.vy] = limit(b.vx, b.vy, MAX_SPEED)

    b.x += b.vx
    b.y += b.vy

    // Wrap around edges if they go off-screen
    if (b.x < -10) b.x = width + 10
    if (b.x > width + 10) b.x = -10
    if (b.y < -10) b.y = height + 10
    if (b.y > height + 10) b.y = -10
  }
}

// ============================================
// Render
// ============================================
const renderBoids = (
  ctx: CanvasRenderingContext2D,
  boids: Boid[],
  width: number,
  height: number,
  dpr: number,
) => {
  // Semi-transparent overlay for trails
  ctx.fillStyle = `rgba(10, 25, 47, ${TRAIL_ALPHA})`
  ctx.fillRect(0, 0, width * dpr, height * dpr)

  ctx.save()
  ctx.scale(dpr, dpr)

  for (const b of boids) {
    const angle = Math.atan2(b.vy, b.vx)
    const speed = Math.sqrt(b.vx * b.vx + b.vy * b.vy)
    const stretch = 1 + (speed / MAX_SPEED) * 0.5 // elongate based on speed
    const radius = 3

    ctx.save()
    ctx.translate(b.x, b.y)
    ctx.rotate(angle)

    ctx.beginPath()
    ctx.ellipse(0, 0, radius * stretch, radius / stretch, 0, 0, Math.PI * 2)
    ctx.fillStyle = b.colour
    ctx.globalAlpha = 0.85
    ctx.fill()
    ctx.restore()
  }

  ctx.restore()
}

// ============================================
// Component
// ============================================
const FlockPage: React.FC = () => {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const wrapperRef = React.useRef<HTMLDivElement>(null)
  const boidsRef = React.useRef<Boid[]>([])
  const cursorRef = React.useRef({ x: 0, y: 0, active: false, repel: false })
  const sizeRef = React.useRef({ width: 0, height: 0 })
  const rafRef = React.useRef<number>(0)

  React.useEffect(() => {
    const canvas = canvasRef.current
    const wrapper = wrapperRef.current
    if (!canvas || !wrapper) return

    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const dpr = window.devicePixelRatio || 1

    // Determine boid count
    const isMobile = window.innerWidth <= MOBILE_BREAKPOINT
    const boidCount = isMobile ? BOID_COUNT_MOBILE : BOID_COUNT_DESKTOP

    // Size canvas
    const resize = () => {
      const rect = wrapper.getBoundingClientRect()
      const w = rect.width
      const h = rect.height
      sizeRef.current = { width: w, height: h }
      canvas.width = w * dpr
      canvas.height = h * dpr
      canvas.style.width = `${w}px`
      canvas.style.height = `${h}px`

      // Clear fully on resize to avoid ghosting
      ctx.fillStyle = '#0A192F'
      ctx.fillRect(0, 0, canvas.width, canvas.height)
    }

    resize()

    // Initialise boids
    boidsRef.current = createBoids(boidCount, sizeRef.current.width, sizeRef.current.height)

    // Observe size changes
    const ro = new ResizeObserver(resize)
    ro.observe(wrapper)

    // Mouse events
    const onMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect()
      cursorRef.current.x = e.clientX - rect.left
      cursorRef.current.y = e.clientY - rect.top
      cursorRef.current.active = true
    }

    const onMouseDown = () => { cursorRef.current.repel = true }
    const onMouseUp = () => { cursorRef.current.repel = false }
    const onMouseLeave = () => { cursorRef.current.active = false; cursorRef.current.repel = false }

    // Touch events
    const onTouchMove = (e: TouchEvent) => {
      const touch = e.touches[0]
      if (!touch) return
      const rect = canvas.getBoundingClientRect()
      cursorRef.current.x = touch.clientX - rect.left
      cursorRef.current.y = touch.clientY - rect.top
      cursorRef.current.active = true
    }

    const onTouchStart = (e: TouchEvent) => {
      const touch = e.touches[0]
      if (!touch) return
      const rect = canvas.getBoundingClientRect()
      cursorRef.current.x = touch.clientX - rect.left
      cursorRef.current.y = touch.clientY - rect.top
      cursorRef.current.active = true
      cursorRef.current.repel = true
    }

    const onTouchEnd = () => {
      cursorRef.current.active = false
      cursorRef.current.repel = false
    }

    canvas.addEventListener('mousemove', onMouseMove)
    canvas.addEventListener('mousedown', onMouseDown)
    canvas.addEventListener('mouseup', onMouseUp)
    canvas.addEventListener('mouseleave', onMouseLeave)
    canvas.addEventListener('touchmove', onTouchMove, { passive: true })
    canvas.addEventListener('touchstart', onTouchStart, { passive: true })
    canvas.addEventListener('touchend', onTouchEnd)

    // Animation loop
    const tick = () => {
      const { width, height } = sizeRef.current
      const { x, y, active, repel } = cursorRef.current

      updateBoids(boidsRef.current, width, height, x, y, active, repel)
      renderBoids(ctx, boidsRef.current, width, height, dpr)

      rafRef.current = requestAnimationFrame(tick)
    }

    rafRef.current = requestAnimationFrame(tick)

    return () => {
      cancelAnimationFrame(rafRef.current)
      ro.disconnect()
      canvas.removeEventListener('mousemove', onMouseMove)
      canvas.removeEventListener('mousedown', onMouseDown)
      canvas.removeEventListener('mouseup', onMouseUp)
      canvas.removeEventListener('mouseleave', onMouseLeave)
      canvas.removeEventListener('touchmove', onTouchMove)
      canvas.removeEventListener('touchstart', onTouchStart)
      canvas.removeEventListener('touchend', onTouchEnd)
    }
  }, [])

  return (
    <div className="container">
      <Header />

      <div className="flock__hero">
        <Link to="/code" className="back-link">&larr; Back to Code</Link>
        <h1>Flock</h1>
        <p>Move your cursor to attract the flock &mdash; click to scatter</p>
        <AccentDots />
      </div>

      <div className="flock__wrapper" ref={wrapperRef}>
        <canvas ref={canvasRef} className="flock__canvas" />
      </div>

      <Footer />
    </div>
  )
}

export default FlockPage
